css:
.flex {
  display: flex;
}
.h-14 {
  height: 3.5rem;
}
.w-14 {
  width: 3.5rem;
}
@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}
.animate-spin {
  animation: spin 1s linear infinite;
}
.flex-row {
  flex-direction: row;
}
.gap-2 {
  gap: 0.5rem;
}
.rounded-full {
  border-radius: 9999px;
}
.bg-gradient-to-tr {
  background-image: linear-gradient(to top right, var(--tw-gradient-stops));
}
.\[animation-delay\:\.7s\] {
  animation-delay: 0.7s;
}
